def largest_subset(a):
    if not a:
        return 0

    # Group numbers by their greatest common divisor (GCD) with all others in the group
    # Specifically, we care about numbers that can pair with others divisible condition
    # The subset will have maximum size if all numbers form a "chain" based on their GCDs
    # So we map every number to its lowest prime factor or 1, but a better approach is to
    # consider all possible subset divisibilities by using dynamic programming

    # This is a classic subset problem where we can use dynamic programming to track valid subsets

    # We'll use dynamic programming to keep track of the largest subset ending with a particular factor
    # This requires sorting and considering each number after sorting to find if it can extend existing subsets

    # The problem can be rephrased as finding the largest subset where for all pairs (a[i], a[j]), a[i] % a[j] == 0 or a[j] % a[i] == 0
    # This is similar to finding the largest chain of divisors, or a clique in a divisibility graph

    a_sorted = sorted(a)
    size = len(a_sorted)

    if size == 0:
        return 0
    elif size == 1:
        return 1

    # Create a DP (dynamic programming) array where dp[i] is the size of the largest subset ending at element i
    dp = [1] * size

    for i in range(size):
        for j in range(i):
            # a[j] divides a[i] or vice versa
            if a[i] % a[j] == 0 or a[j] % a[i] == 0:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1

    return max(dp)
